const lobsterPotCubes=()=>{const parts:Cube[]=[],add=(id:string,name:string,from:Vec3,to:Vec3,color:string,material:string)=>parts.push(cube(id,name,from,to,color,material)),wicker="#8b6538",wickerLight="#b1884d",hoop="#403526",rope="#c4a566";add("pot_base_front","Woven base front",[3,1,3],[13,2,5],wicker,"wicker wood");add("pot_base_back","Woven base back",[3,1,11],[13,2,13],wicker,"wicker wood");add("pot_base_left","Woven base left",[3,1,5],[5,2,11],wicker,"wicker wood");add("pot_base_right","Woven base right",[11,1,5],[13,2,11],wicker,"wicker wood");[[3,3],[7.5,3],[12,3],[3,12],[7.5,12],[12,12]].forEach(([x,z],index)=>add(`pot_stave_fb_${index}`,"Vertical wicker stave",[x,2,z],[x+1,12,z+1],index%2?wickerLight:wicker,"wicker wood"));[[3,7.5],[12,7.5]].forEach(([x,z],index)=>add(`pot_stave_side_${index}`,"Side wicker stave",[x,2,z],[x+1,12,z+1],wickerLight,"wicker wood"));[4,8,11].forEach((y,ring)=>{add(`pot_hoop_${ring}_front`,"Dark binding hoop",[2.5,y,2.5],[13.5,y+1,3.5],hoop,"dark iron");add(`pot_hoop_${ring}_back`,"Dark binding hoop",[2.5,y,12.5],[13.5,y+1,13.5],hoop,"dark iron");add(`pot_hoop_${ring}_left`,"Dark binding hoop",[2.5,y,3.5],[3.5,y+1,12.5],hoop,"dark iron");add(`pot_hoop_${ring}_right`,"Dark binding hoop",[12.5,y,3.5],[13.5,y+1,12.5],hoop,"dark iron")});add("pot_neck_front","Narrow neck front",[5,12,5],[11,13,6],wicker,"wicker wood");add("pot_neck_back","Narrow neck back",[5,12,10],[11,13,11],wicker,"wicker wood");add("pot_neck_left","Narrow neck left",[5,12,6],[6,13,10],wicker,"wicker wood");add("pot_neck_right","Narrow neck right",[10,12,6],[11,13,10],wicker,"wicker wood");[[5,5],[10,5],[5,10],[10,10]].forEach(([x,z],index)=>add(`pot_neck_stave_${index}`,"Neck stave",[x,13,z],[x+1,16,z+1],wickerLight,"wicker wood"));add("pot_mouth_front","Pot mouth rim",[5,15,5],[11,16,6],hoop,"dark iron");add("pot_mouth_back","Pot mouth rim",[5,15,10],[11,16,11],hoop,"dark iron");add("pot_mouth_left","Pot mouth rim",[5,15,6],[6,16,10],hoop,"dark iron");add("pot_mouth_right","Pot mouth rim",[10,15,6],[11,16,10],hoop,"dark iron");add("pot_rope_left","Rope handle left",[5,16,7],[6,18,8],rope,"hemp rope");add("pot_rope_top","Rope handle",[5,17,7],[11,18,8],rope,"hemp rope");add("pot_rope_right","Rope handle right",[10,16,7],[11,18,8],rope,"hemp rope");return parts};
const assertNoCubeVolumeOverlaps=(parts:Cube[])=>{for(let i=0;i<parts.length;i++)for(let j=i+1;j<parts.length;j++){const overlap=([0,1,2] as const).every(axis=>Math.min(parts[i].to[axis],parts[j].to[axis])-Math.max(parts[i].from[axis],parts[j].from[axis])>.0001);if(overlap)throw new Error(`Overlapping model parts: ${parts[i].id} and ${parts[j].id}`)}return parts};
const overlapFreeLobsterPotCubes=()=>{const parts:Cube[]=[],add=(id:string,name:string,from:Vec3,to:Vec3,color:string,material:string)=>parts.push(cube(id,name,from,to,color,material)),wickerDark="#7a5326",wicker="#a3742f",wickerLight="#c99a4b",hoop="#4a3a24",rope="#d8bd7f",shadow="#241a10";
  // Each course is an octagonal ring (four walls plus four one-wide corner steps), so the pot
  // reads as a round bellied creel instead of a square cage.
  const course=(tag:string,label:string,y0:number,y1:number,r:number,color:string,material:string)=>{const a=r-2,lo=8-r,hi=8+r;
    add(`pot_${tag}_f`,`${label} front`,[8-a,y0,lo],[8+a,y1,lo+1],color,material);add(`pot_${tag}_b`,`${label} back`,[8-a,y0,hi-1],[8+a,y1,hi],color,material);
    add(`pot_${tag}_l`,`${label} left`,[lo,y0,8-a],[lo+1,y1,8+a],color,material);add(`pot_${tag}_r`,`${label} right`,[hi-1,y0,8-a],[hi,y1,8+a],color,material);
    add(`pot_${tag}_fl`,`${label} front-left corner`,[lo+1,y0,lo+1],[lo+2,y1,lo+2],color,material);add(`pot_${tag}_fr`,`${label} front-right corner`,[hi-2,y0,lo+1],[hi-1,y1,lo+2],color,material);
    add(`pot_${tag}_bl`,`${label} back-left corner`,[lo+1,y0,hi-2],[lo+2,y1,hi-1],color,material);add(`pot_${tag}_br`,`${label} back-right corner`,[hi-2,y0,hi-2],[hi-1,y1,hi-1],color,material)};
  add("pot_base","Woven base",[4.5,0,4.5],[11.5,1,11.5],wickerDark,"woven wicker");
  course("belly","Bellied lower weave",1,4,6,wicker,"woven wicker");course("hoop1","Lower binding hoop",4,4.9,6.15,hoop,"tarred binding hoop");
  course("mid","Mid weave",4.9,7.6,5.7,wickerLight,"woven wicker");course("hoop2","Middle binding hoop",7.6,8.5,5.85,hoop,"tarred binding hoop");
  course("shoulder","Tapering shoulder weave",8.5,11,5.1,wicker,"woven wicker");course("hoop3","Upper binding hoop",11,11.9,5.25,hoop,"tarred binding hoop");
  course("neck","Funnel neck weave",11.9,14,4.2,wickerLight,"woven wicker");course("mouth","Pot mouth rim",14,15,4.35,hoop,"tarred binding hoop");
  add("pot_funnel","Dark funnel entrance",[6,13.4,6],[10,14,10],shadow,"pot interior shadow");
  add("pot_rope_l","Rope handle left",[5.5,15,7.5],[6.5,17,8.5],rope,"hemp rope");add("pot_rope_r","Rope handle right",[9.5,15,7.5],[10.5,17,8.5],rope,"hemp rope");
  add("pot_rope_top","Rope handle crown",[5.5,17,7.5],[10.5,18,8.5],rope,"hemp rope");return assertNoCubeVolumeOverlaps(parts)};
