  const invalid=projects.filter(project=>(modelKind(project)==="structure"?validationStructure(project):validation(project)).some(note=>note.level==="error"));if(invalid.length){alert(`Fix export errors in: ${invalid.map(project=>project.name).join(", ")}`);return}
  const usedIdentities=new Set<string>(),targets=projects.map(project=>{const ns=namespace(project),baseId=slug(project.name);let id=baseId,suffix=slug(project.id);if(usedIdentities.has(`${ns}:${id}`))id=`${baseId}_${suffix}`;let attempt=2;while(usedIdentities.has(`${ns}:${id}`))id=`${baseId}_${suffix}_${attempt++}`;usedIdentities.add(`${ns}:${id}`);return{project,ns,id}});
  const files:{name:string;data:Uint8Array}[]=[],add=(name:string,data:string|Uint8Array)=>files.push({name,data:typeof data==="string"?textBytes(data):data}),manifest:{id:string;name:string;kind:ModelKind;format:string}[]=[];
  add("resource-pack/pack.mcmeta",JSON.stringify({pack:{description:`Blocksmith collection: ${collectionName}`,pack_format:88}},null,2));
  const attributions=[...new Set(projects.map(project=>project.attribution).filter((value):value is string=>Boolean(value)))];if(attributions.length)add("CREDITS.txt",`${attributions.join("\n")}\n`);
  for(const{project,ns,id}of targets){const kind=modelKind(project);if(kind==="structure"){add(`structures/${id}.schem`,await schematicBytes(project));manifest.push({id:`${ns}:${id}`,name:project.name,kind,format:"sponge_v3_schematic"});continue}const model=minecraftJson(project);add(`resource-pack/assets/${ns}/models/${kind==="block"?"block":"item"}/${id}.json`,JSON.stringify(model,null,2));add(`resource-pack/assets/${ns}/items/${id}.json`,JSON.stringify({model:{type:"minecraft:model",model:`${ns}:${kind==="block"?"block":"item"}/${id}`}},null,2));if(project.sprite)add(`resource-pack/assets/${ns}/textures/item/${id}.png`,await spritePng(project.sprite));else await addProjectBlockTextures(project,id,`resource-pack/assets/${ns}/textures/block`,add);const clips=clipsFor(project);if(!project.sprite&&clips.length)for(const bone of bonesFor(project)){const parts=project.cubes.filter(part=>(part.boneId||part.id)===bone.id),bonePath=`${id}/bone/${slug(bone.name)}`;add(`resource-pack/assets/${ns}/models/item/${bonePath}.json`,JSON.stringify(minecraftJson(project,parts,bone.pivot),null,2));add(`resource-pack/assets/${ns}/items/${bonePath}.json`,JSON.stringify({model:{type:"minecraft:model",model:`${ns}:item/${bonePath}`}},null,2))}add(`paper/content/${ns}/${id}.json`,JSON.stringify(paperContentData(project,ns,id),null,2));if(clips.length)add(`paper/content/${ns}/animations/${id}.animation.json`,JSON.stringify(animationExportData(project,ns,id),null,2));manifest.push({id:`${ns}:${id}`,name:project.name,kind,format:"paper_content"})}
