export default function ModelMaker(){
  const [library,setLibrary]=useState<Project[]>(BUILTINS);
  const [project,setProject]=useState<Project>(clone(atm));
  const [selected,setSelected]=useState<string|null>(atm.cubes[6].id);
  const [previewMode,setPreviewMode]=useState<PreviewMode>("studio");
  const [copied,setCopied]=useState(false);
  const [libraryFilter,setLibraryFilter]=useState("All");
  const [libraryPack,setLibraryPack]=useState("All Packs");
  const [librarySearch,setLibrarySearch]=useState("");
  const [libraryType,setLibraryType]=useState<LibraryContentType>("All Content");
  const [libraryOpen,setLibraryOpen]=useState(false);
  const [spriteEditorOpen,setSpriteEditorOpen]=useState(false);
  const [dockMode,setDockMode]=useState<"library"|"animate">("library");
  const [activeClipId,setActiveClipId]=useState<string|null>(null);
  const [animationTick,setAnimationTick]=useState(0);
  const [playing,setPlaying]=useState(false);
  const [structureLayer,setStructureLayer]=useState(0);
  const [structureBrush,setStructureBrush]=useState("minecraft:stone_bricks");
  const [history,setHistory]=useState<Project[]>([]);const [future,setFuture]=useState<Project[]>([]);const [deletedIds,setDeletedIds]=useState<string[]>([]);const [hydrated,setHydrated]=useState(false);const [saveStatus,setSaveStatus]=useState<"idle"|"saving"|"saved"|"error">("idle");
  const modelInput=useRef<HTMLInputElement>(null);
  const pendingSave=useRef(false);
  const selectedCube=project.cubes.find(c=>c.id===selected)||null;
  const bones=useMemo(()=>bonesFor(project),[project]);
  const selectedBone=selectedCube?bones.find(bone=>bone.id===(selectedCube.boneId||selectedCube.id))||null:null;
  const activeClip=clipsFor(project).find(clip=>clip.id===activeClipId)||clipsFor(project)[0];
  const selectedTrack=selectedBone?sampleTrack(activeClip,selectedBone.id,animationTick):{rotation:[0,0,0] as Vec3,position:[0,0,0] as Vec3};
  const jsonPreview=useMemo(()=>JSON.stringify(minecraftJson(project),null,2),[project]);
  const checks=useMemo(()=>modelKind(project)==="structure"?validationStructure(project):validation(project),[project]);
  const exportBlocked=checks.some(check=>check.level==="error");
  const categoryTabs=useMemo(()=>["All",...CATEGORY_OPTIONS.filter(category=>library.some(model=>projectCategory(model)===category))],[library]);
  const packOptions=useMemo(()=>["All Packs",...[...new Set(library.map(projectPack))].sort()],[library]);
  const libraryResults=useMemo(()=>library.filter(model=>(libraryType==="All Content"||libraryContentType(model)===libraryType)&&(libraryPack==="All Packs"||projectPack(model)===libraryPack)&&(libraryFilter==="All"||projectCategory(model)===libraryFilter)&&`${model.name} ${model.description} ${projectGroup(model)} ${projectPack(model)}`.toLowerCase().includes(librarySearch.trim().toLowerCase())),[library,libraryType,libraryPack,libraryFilter,librarySearch]);
  const visibleGroups=useMemo(()=>{const groups=new Map<string,Project[]>();libraryResults.forEach(model=>{const key=`${projectPack(model)}|||${projectGroup(model)}`;groups.set(key,[...(groups.get(key)||[]),model])});return[...groups.entries()]},[libraryResults]);
  const copyTestCommand=async()=>{await navigator.clipboard.writeText(giveCommand(project));setCopied(true);setTimeout(()=>setCopied(false),1600)};

  useEffect(()=>{try{const deleted=JSON.parse(localStorage.getItem("blocksmith-deleted-models-v1")||"[]") as string[],deletedSet=new Set(deleted),saved=JSON.parse(localStorage.getItem("blocksmith-library-v2")||"[]") as Project[];setDeletedIds(deleted);const merged=saved.filter(project=>!RETIRED_BUILTIN_IDS.has(project.id)&&!deletedSet.has(project.id));BUILTINS.filter(b=>!deletedSet.has(b.id)).forEach(b=>{const i=merged.findIndex(p=>p.id===b.id);if(i<0)merged.push(clone(b));else if((merged[i].revision||0)<b.revision&&merged[i].source!=="local")merged[i]=clone(b)});const builtInIds=new Set(BUILTINS.map(b=>b.id)),ordered=[...BUILTINS.filter(b=>!deletedSet.has(b.id)).map(b=>clone(merged.find(p=>p.id===b.id)||b)),...merged.filter(p=>!builtInIds.has(p.id))],initial=ordered[0]||blankItemProject();setLibrary(ordered.length?ordered:[initial]);setProject(clone(initial));setSelected(initial.sprite?null:initial.cubes[0]?.id||null)}catch{}setHydrated(true)},[]);
  useEffect(()=>{if(!hydrated)return;try{const localProjects=library.filter(project=>project.source==="local");localStorage.setItem("blocksmith-library-v2",JSON.stringify(localProjects));if(pendingSave.current)setSaveStatus("saved")}catch{if(pendingSave.current)setSaveStatus("error")}finally{pendingSave.current=false}},[library,hydrated]);
  useEffect(()=>{if(hydrated)localStorage.setItem("blocksmith-deleted-models-v1",JSON.stringify(deletedIds))},[deletedIds,hydrated]);
  useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==="Escape")setLibraryOpen(false)};window.addEventListener("keydown",close);return()=>window.removeEventListener("keydown",close)},[]);
  useEffect(()=>{if(!playing||!activeClip)return;const timer=setInterval(()=>setAnimationTick(tick=>{const next=tick+1;if(next<=activeClip.lengthTicks)return next;if(activeClip.loop)return 0;setPlaying(false);return activeClip.lengthTicks}),50);return()=>clearInterval(timer)},[playing,activeClip]);
  const commit=(next:Project)=>{setHistory(h=>[...h.slice(-39),clone(project)]);setFuture([]);setProject(next)};
  const beginSpriteStroke=()=>{setHistory(h=>[...h.slice(-39),clone(project)]);setFuture([])};
  const updateSprite=(sprite:(string|null)[])=>setProject(current=>({...current,sprite}));
  const updateCube=(patch:Partial<Cube>)=>selectedCube&&commit({...project,cubes:project.cubes.map(c=>c.id===selectedCube.id?{...c,...patch}:c)});
  const organize=(patch:Partial<Pick<Project,"category"|"group"|"pack">>)=>{const next={...project,...patch};setProject(next);setLibrary(items=>items.map(item=>item.id===project.id?{...item,...patch}:item))};
  const save=()=>{const saved={...clone(project),source:"local" as const,revision:Math.max(1,project.revision||0)+1};pendingSave.current=true;setSaveStatus("saving");setProject(saved);setLibrary(items=>{const i=items.findIndex(p=>p.id===saved.id);return i<0?[saved,...items]:items.map((p,n)=>n===i?saved:p)})};
  const open=(model:Project)=>{const opened=clone(model);if(opened.structure){opened.structure.blocks=resolveStructureConnections(opened.structure.blocks);opened.cubes=structureBlocksToCubes(opened.structure.blocks)}setProject(opened);setSelected(opened.sprite?null:opened.cubes[0]?.id||null);setSpriteEditorOpen(Boolean(opened.sprite));setActiveClipId(opened.animations?.[0]?.id||null);setAnimationTick(0);setPlaying(false);setHistory([]);setFuture([])};
  const newModel=()=>{const blank=blankItemProject();setLibrary(items=>[blank,...items]);open(blank);setLibraryOpen(false)};
  const newCharacter=()=>{const blank=blankCharacterProject();setLibrary(items=>[blank,...items]);open(blank);setLibraryOpen(false)};
  const newStructure=()=>{const blank:Project={id:uid("structure"),name:"Untitled Structure",description:"A new Minecraft block structure.",cubes:[],source:"local",revision:1,kind:"structure",namespace:"blocksmith",category:"Structures",group:"Ungrouped",pack:"Unassigned Pack",structure:{size:[16,16,16],blocks:[]}};setLibrary(items=>[blank,...items]);open(blank);setStructureLayer(0);setLibraryOpen(false)};
  const setStructureBlocks=(blocks:StructureBlock[])=>{const normalized=resolveStructureConnections(blocks);commit({...project,cubes:structureBlocksToCubes(normalized),structure:{size:project.structure?.size||[16,16,16],blocks:normalized}})};
  const paintStructure=(x:number,z:number)=>{if(!project.structure)return;const y=structureLayer,key=`${x},${y},${z}`,current=project.structure.blocks.find(block=>`${block.x},${block.y},${block.z}`===key),removeKeys=new Set([key]);if(current&&parseBlockState(current.state).id.endsWith("_door")){const half=parseBlockState(current.state).properties.half||"lower";removeKeys.add(`${x},${y+(half==="lower"?1:-1)},${z}`)}let others=project.structure.blocks.filter(block=>!removeKeys.has(`${block.x},${block.y},${block.z}`));if(structureBrush==="minecraft:air"){setStructureBlocks(others);return}const brush=parseBlockState(structureBrush);if(brush.id.endsWith("_door")){if(y+1>=project.structure.size[1])return;others=others.filter(block=>`${block.x},${block.y},${block.z}`!==`${x},${y+1},${z}`);const properties={facing:brush.properties.facing||"north",hinge:brush.properties.hinge||"left",open:brush.properties.open||"false",powered:brush.properties.powered||"false"};setStructureBlocks([...others,{id:`structure_${x}_${y}_${z}_door_lower`,x,y,z,state:formatBlockState(brush.id,{...properties,half:"lower"})},{id:`structure_${x}_${y+1}_${z}_door_upper`,x,y:y+1,z,state:formatBlockState(brush.id,{...properties,half:"upper"})}]);return}setStructureBlocks([...others,{id:`structure_${x}_${y}_${z}`,x,y,z,state:structureBrush}])};
  const fillStructureLayer=()=>{if(!project.structure)return;const brush=parseBlockState(structureBrush),pairedDoor=brush.id.endsWith("_door"),layers=new Set([structureLayer,...(pairedDoor?[structureLayer+1]:[])]),others=project.structure.blocks.filter(block=>!layers.has(block.y));if(structureBrush==="minecraft:air"){setStructureBlocks(others);return}if(pairedDoor&&structureLayer+1>=project.structure.size[1])return;const additions:StructureBlock[]=[];for(let z=0;z<project.structure.size[2];z++)for(let x=0;x<project.structure.size[0];x++){if(pairedDoor){const properties={facing:brush.properties.facing||"north",hinge:brush.properties.hinge||"left",open:brush.properties.open||"false",powered:brush.properties.powered||"false"};additions.push({id:`structure_${x}_${structureLayer}_${z}_door_lower`,x,y:structureLayer,z,state:formatBlockState(brush.id,{...properties,half:"lower"})},{id:`structure_${x}_${structureLayer+1}_${z}_door_upper`,x,y:structureLayer+1,z,state:formatBlockState(brush.id,{...properties,half:"upper"})})}else additions.push({id:`structure_${x}_${structureLayer}_${z}`,x,y:structureLayer,z,state:structureBrush})}setStructureBlocks([...others,...additions])};
  const resizeStructure=(size:Vec3)=>{if(!project.structure)return;const blocks=project.structure.blocks.filter(block=>block.x<size[0]&&block.y<size[1]&&block.z<size[2]);commit({...project,cubes:structureBlocksToCubes(blocks),structure:{size,blocks}});setStructureLayer(layer=>Math.min(layer,size[1]-1))};
  const cloneLibraryModel=(model:Project,openCopy=false)=>{const base=`${model.name} Copy`,names=new Set(library.map(item=>item.name.toLowerCase()));let name=base,suffix=2;while(names.has(name.toLowerCase()))name=`${base} ${suffix++}`;const copy={...clone(model),id:uid("model"),name,source:"local" as const,revision:1};setLibrary(items=>[copy,...items]);if(openCopy)open(copy)};
  const duplicate=()=>cloneLibraryModel(project,true);
  const deleteModel=()=>{if(!confirm(`Delete “${project.name}” from your library? This cannot be undone.`))return;let remaining=library.filter(p=>p.id!==project.id);setDeletedIds(ids=>ids.includes(project.id)?ids:[...ids,project.id]);if(!remaining.length)remaining=[blankItemProject()];setLibrary(remaining);open(remaining[0]);setLibraryOpen(false)};
  const addCube=()=>{const next=cube(uid(),"New cube",[5,5,5],[11,11,11],COLORS[project.cubes.length%COLORS.length],"custom");commit({...project,cubes:[...project.cubes,next],...(project.bones?{bones:[...bones,{id:next.id,name:next.name,parentId:null,pivot:[8,8,8]}]}:{})});setSelected(next.id)};
  const updateBone=(patch:Partial<Bone>)=>{if(!selectedBone)return;commit({...project,bones:bones.map(bone=>bone.id===selectedBone.id?{...bone,...patch}:bone),cubes:project.cubes.map(part=>part.id===selectedCube?.id?{...part,boneId:selectedBone.id}:part)})};
  const addClip=()=>{const clip:AnimationClip={id:uid("clip"),name:`Animation ${clipsFor(project).length+1}`,lengthTicks:20,loop:true,keyframes:[]};commit({...project,bones,animations:[...clipsFor(project),clip]});setActiveClipId(clip.id);setAnimationTick(0);setDockMode("animate")};
  const updateClip=(patch:Partial<AnimationClip>)=>{if(!activeClip)return;commit({...project,bones,animations:clipsFor(project).map(clip=>clip.id===activeClip.id?{...clip,...patch}:clip)})};
  const setTrackValue=(field:"rotation"|"position",value:Vec3)=>{if(!activeClip||!selectedBone)return;const tick=Math.max(0,Math.min(activeClip.lengthTicks,animationTick)),existing=activeClip.keyframes.find(frame=>frame.boneId===selectedBone.id&&frame.tick===tick),frame:Keyframe=existing?{...existing,[field]:value}:{id:uid("key"),tick,boneId:selectedBone.id,rotation:field==="rotation"?value:[0,0,0],position:field==="position"?value:[0,0,0],interpolation:"linear"};updateClip({keyframes:existing?activeClip.keyframes.map(item=>item.id===existing.id?frame:item):[...activeClip.keyframes,frame]})};
  const deleteKeyframe=()=>{if(!activeClip||!selectedBone)return;updateClip({keyframes:activeClip.keyframes.filter(frame=>!(frame.boneId===selectedBone.id&&frame.tick===animationTick))})};
  const undo=()=>{const previous=history.at(-1);if(!previous)return;setFuture(f=>[clone(project),...f]);setProject(previous);setHistory(h=>h.slice(0,-1))};
  const redo=()=>{const next=future[0];if(!next)return;setHistory(h=>[...h,clone(project)]);setProject(next);setFuture(f=>f.slice(1))};
  const importModel=(e:ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;file.text().then(raw=>{try{const data=JSON.parse(raw),parts:Cube[]=(data.elements||[]).map((el:{name?:string;from:Vec3;to:Vec3},i:number)=>cube(uid(),el.name||`Cube ${i+1}`,el.from,el.to,COLORS[i%COLORS.length]));const imported:Project={id:uid("model"),name:file.name.replace(/\.json$/i,""),description:"Imported Minecraft model",cubes:parts,source:"local",revision:1};setLibrary(items=>[imported,...items]);open(imported)}catch{alert("That file is not valid Minecraft model JSON.")}});e.target.value=""};

  return <main className={`app-shell ${dockMode==="animate"&&modelKind(project)!=="structure"?"animation-open":""} ${modelKind(project)==="structure"?"structure-open":""}`}>
    <header className="topbar">
      <div className="brand"><span className="brand-cube">B</span><div><strong>BLOCKSMITH</strong><small>CODEX MODEL WORKBENCH</small></div></div>
      <div className="project-title"><span className="status-dot"/><input aria-label="Project name" value={project.name} onChange={e=>setProject({...project,name:e.target.value})}/>{hasPlacementFootprint(project)&&<span className="footprint-chip">{placementFootprint(project).join(" × ")} BLOCKS</span>}</div>
      <div className="top-actions"><button className="tool-button" onClick={undo} disabled={!history.length} title="Undo">↶</button><button className="tool-button" onClick={redo} disabled={!future.length} title="Redo">↷</button><button className="secondary nav-action" onClick={()=>{setLibraryOpen(true);setDockMode("library")}}>Library</button><button className={`secondary nav-action ${dockMode==="animate"?"active":""}`} disabled={modelKind(project)==="structure"} onClick={()=>setDockMode(mode=>mode==="animate"?"library":"animate")}>Animate</button><button className="secondary" onClick={save} disabled={saveStatus==="saving"}>{saveStatus==="saving"?"Saving…":saveStatus==="saved"?"Saved ✓":"Save"}</button>{saveStatus==="error"&&<span className="save-error" role="alert" title="Browser storage is full. Export the project before clearing older local models.">Save failed</span>}<button className="primary" disabled={exportBlocked} onClick={()=>modelKind(project)==="structure"?exportSchematic(project):exportPaperBundle(project)}>{modelKind(project)==="structure"?"Export .schem":"Export Paper bundle"}</button></div>
      <button className="top-delete-model" onClick={deleteModel}>Delete</button>
    </header>
    <section className="workspace">
      <aside className="left-panel panel"><div className="panel-heading"><div><span className="eyebrow">OUTLINER</span><h2>{project.sprite?"16 × 16 vanilla sprite":`${project.cubes.length} model parts`}</h2></div>{!project.sprite&&<button className="mini-add" onClick={addCube}>+</button>}</div><div className="tree-label">⌄ ◈ {project.name}</div>{project.sprite?<div className="sprite-info"><b>{project.spriteParent==="generated"?"FLAT INVENTORY ITEM":"FLAT HANDHELD ITEM"}</b><p>Minecraft extrudes the transparent sprite and applies its native {project.spriteParent==="generated"?"inventory-item":"handheld-tool"} transforms.</p><div className="sprite-palette">{[...new Set(project.sprite.filter(Boolean))].map(color=><i key={color!} style={{background:color!}}/>)}</div></div>:<><div className="cube-list">{project.cubes.map(c=><button key={c.id} className={`cube-row ${selected===c.id?"active":""}`} onClick={()=>setSelected(c.id)}><span className="cube-glyph">◆</span><span>{c.name}</span><i style={{background:c.color}}/></button>)}</div><button className="add-part" onClick={addCube}>＋ Add cube</button></>}<div className="tips"><strong>Codex workflow</strong><p>Describe a model in this Codex chat.</p><p>Codex adds it here, then publishes it.</p></div></aside>
      <section className={`stage preview-${previewMode}`}><div className="stage-tools"><span className="badge">{previewMode==="studio"?"MODEL WORKSPACE":"LOCKED INVENTORY CHECK"}</span>{hasPlacementFootprint(project)&&<span className="badge footprint-badge">FOOTPRINT {placementFootprint(project).join(" × ")}</span>}<span className="badge"><i/> {activeClip?`${activeClip.name} · T${animationTick}`:"TEXTURED"}</span></div><div className="preview-tabs" role="group" aria-label="Model preview"><button className={previewMode==="studio"?"active":""} onClick={()=>setPreviewMode("studio")}>Model space</button><button className={previewMode==="gui"?"active":""} onClick={()=>setPreviewMode("gui")}>Inventory check</button></div><div className="minecraft-test"><span>AUTHORITATIVE TEST</span><code>{giveCommand(project)}</code><div><button disabled={exportBlocked} onClick={()=>exportMinecraftTestPack(project)}>Download test bundle</button><button onClick={copyTestCommand}>{copied?"Copied!":"Copy command"}</button></div></div><Viewport project={project} selected={selected} onSelect={setSelected} previewMode={previewMode} animationClip={activeClip} animationTick={animationTick}/><div className="axis"><span className="x">X</span><span className="y">Y</span><span className="z">Z</span></div><div className="stage-note">{previewMode==="studio"?"Geometry inspection · Drag to orbit · Scroll to zoom":"Locked orthographic check · Verify held views inside Minecraft"}</div></section>
      <aside className="right-panel panel"><div className="panel-heading"><div><span className="eyebrow">PAPER 26.2 TARGET</span><h2>{selectedCube?.name||"Model settings"}</h2></div>{selectedCube&&<button className="delete" onClick={()=>{commit({...project,cubes:project.cubes.filter(c=>c.id!==selectedCube.id)});setSelected(null)}}>×</button>}</div><section className="target-card">{project.sprite&&<><label className="field-label">MODEL NAME<input value={project.name} onChange={e=>setProject({...project,name:e.target.value})}/></label><label className="field-label">COLLECTION<input value={projectGroup(project)} onChange={e=>organize({group:e.target.value})}/></label></>}<label className="field-label">CONTENT TYPE<select value={modelKind(project)} onChange={e=>setProject({...project,kind:e.target.value as ModelKind})}><option value="item">Custom item</option><option value="block">Placeable block</option><option value="furniture">Furniture / display</option><option value="mob">Animated mob</option></select></label><label className="field-label">NAMESPACE<input value={project.namespace||"blocksmith"} onChange={e=>setProject({...project,namespace:slug(e.target.value)})}/></label>{modelKind(project)==="mob"&&<label className="field-label">AI + HITBOX ANCHOR<input value={project.baseEntity||"minecraft:zombie"} onChange={e=>setProject({...project,baseEntity:e.target.value})}/></label>}{hasPlacementFootprint(project)&&<PlacementFootprintEditor project={project} onChange={placementSize=>setProject({...project,placementSize})}/>}<div className={`target-summary ${modelKind(project)}`}><b>{modelKind(project)==="mob"?"DISPLAY RIG":modelKind(project)==="item"?(project.spriteParent==="generated"?"GENERATED ITEM":"HANDHELD ITEM"):modelKind(project)==="block"?"SOLID PLACEMENT":"DISPLAY MODEL"}</b><span>{modelKind(project)==="mob"?"Idle, walk and attack tracks included":modelKind(project)==="item"?(project.spriteParent==="generated"?"Uses Minecraft’s standard inventory-item transforms":"Uses Minecraft’s standard handheld-tool transforms"):modelKind(project)==="block"?"Model plus solid placement metadata":"Vanilla-client resource-pack content"}</span></div></section>{selectedCube?<div className="inspector"><label className="field-label">NAME<input value={selectedCube.name} onChange={e=>updateCube({name:e.target.value})}/></label><VectorEditor label="FROM" value={selectedCube.from} onChange={from=>updateCube({from})}/><VectorEditor label="TO" value={selectedCube.to} onChange={to=>updateCube({to})}/><VectorEditor label="ROTATION" value={selectedCube.rotation} onChange={rotation=>updateCube({rotation})}/><label className="field-label">PROCEDURAL MATERIAL<input value={selectedCube.material||""} onChange={e=>updateCube({material:e.target.value})}/></label><div className="field-label">BASE COLOR<div className="swatches">{COLORS.map(color=><button aria-label={`Set color ${color}`} key={color} className={selectedCube.color===color?"chosen":""} style={{background:color}} onClick={()=>updateCube({color})}/>)}</div></div></div>:<p className="empty">{project.sprite?"Edit this icon’s name, collection, export target, and pixels.":"Select a part to edit its geometry and material."}</p>}<section className="validation-card"><span className="eyebrow">EXPORT CHECK</span>{checks.map((check,i)=><p key={i} className={check.level}><i/>{check.text}</p>)}</section><section className="texture-card procedural-card"><span className="eyebrow">MINECRAFT MATERIAL SYSTEM</span><div className="material-preview"><i/><i/><i/><i/><i/><i/><i/><i/><i/></div><strong>Procedural 16×16 textures</strong><p>Export creates real PNG textures for every part, locked to the model’s faces.</p></section><details className="json-box"><summary>Minecraft JSON preview</summary><pre>{jsonPreview}</pre></details></aside>
    </section>
    {modelKind(project)==="item"&&(spriteEditorOpen?<aside className="sprite-editor-tray"><button className="sprite-editor-collapse" onClick={()=>setSpriteEditorOpen(false)} aria-label="Hide pixel editor">Hide editor ›</button>{project.sprite?<SpriteEditor sprite={project.sprite} onBegin={beginSpriteStroke} onChange={updateSprite} onCenter={()=>commit({...project,sprite:centerSpritePixels(project.sprite!)})} onClear={()=>commit({...project,sprite:Array(256).fill(null)})} onUndo={undo} onRedo={redo} canUndo={history.length>0} canRedo={future.length>0}/>:<section className="sprite-editor-empty"><span className="eyebrow">FLAT ITEM WORKFLOW</span><strong>Create a native Minecraft sprite</strong><p>Paint a 16 × 16 texture that Minecraft can extrude and display as a real inventory item.</p><button onClick={()=>commit({...project,sprite:Array(256).fill(null),spriteParent:"generated"})}>Create 16×16 sprite</button></section>}</aside>:<button className="sprite-editor-toggle" onClick={()=>setSpriteEditorOpen(true)}>✎ Pixel editor</button>)}
{project.skin&&<div className="character-export-bar"><button onClick={()=>void downloadCharacterSkin(project)}>Download skin PNG</button><button className="primary" onClick={()=>void exportCharacterBundle(project)}>Export Blackwake NPC ZIP</button></div>}
    {project.skin&&<CharacterDesigner project={project} onBegin={beginSpriteStroke} onChange={patch=>setProject(current=>({...current,...patch}))}/>}
    {modelKind(project)==="structure"&&project.structure&&<StructureEditor project={project} layer={Math.min(structureLayer,project.structure.size[1]-1)} brush={structureBrush} onLayer={setStructureLayer} onBrush={setStructureBrush} onPaint={paintStructure} onFill={fillStructureLayer} onResize={resizeStructure}/>}
    {dockMode==="animate"&&modelKind(project)!=="structure"&&<section className="library-dock animation-dock">
      <div className="library-title">
        <div><span className="eyebrow">JAVA DISPLAY RIG</span><h2>20 ticks = 1 second</h2></div>
        <div className="rig-standard"><b>MINECRAFT JAVA · Y UP</b><span>Front −Z · Back +Z · right-handed</span><span>Pixels · degrees · 20 TPS</span></div>
      </div>
      <div className="animation-workspace">
        <div className="clip-row"><button className="add-clip" onClick={addClip}>＋ Clip</button>{clipsFor(project).map(clip=><button key={clip.id} className={activeClip?.id===clip.id?"active":""} onClick={()=>{setActiveClipId(clip.id);setAnimationTick(0);setPlaying(false)}}>{clip.name}</button>)}</div>
        {activeClip?<><div className="animation-settings"><label>CLIP<input value={activeClip.name} onChange={e=>updateClip({name:e.target.value})}/></label><label>LENGTH (TICKS)<input type="number" min="1" value={activeClip.lengthTicks} onChange={e=>updateClip({lengthTicks:Math.max(1,Number(e.target.value))})}/></label><label className="loop-check"><input type="checkbox" checked={activeClip.loop} onChange={e=>updateClip({loop:e.target.checked})}/> LOOP</label><button className="play" onClick={()=>setPlaying(value=>!value)}>{playing?"Ⅱ Pause":"▶ Play"}</button></div><div className="timeline"><div className="timeline-labels"><b>TICK {animationTick}</b><span>{(animationTick/20).toFixed(2)}s / {(activeClip.lengthTicks/20).toFixed(2)}s</span></div><div className="timeline-rail">{activeClip.keyframes.map(frame=><i key={frame.id} className={frame.boneId===selectedBone?.id?"selected":""} style={{left:`${frame.tick/activeClip.lengthTicks*100}%`}} title={`${frame.boneId} · tick ${frame.tick}`}/>) }<input aria-label="Animation timeline" type="range" min="0" max={activeClip.lengthTicks} step="1" value={animationTick} onChange={e=>{setAnimationTick(Number(e.target.value));setPlaying(false)}}/></div></div><div className="keyframe-editor">{selectedBone?<><div className="bone-settings"><label>BONE<strong>{selectedBone.name}</strong></label><label>PARENT<select value={selectedBone.parentId||""} onChange={e=>updateBone({parentId:e.target.value||null})}><option value="">Root</option>{bones.filter(bone=>bone.id!==selectedBone.id).map(bone=><option key={bone.id} value={bone.id}>{bone.name}</option>)}</select></label><VectorEditor label="PIVOT (PIXELS)" value={selectedBone.pivot} onChange={pivot=>updateBone({pivot})}/></div><div className="track-values"><VectorEditor label="ROTATION (DEGREES)" value={selectedTrack.rotation} onChange={value=>setTrackValue("rotation",value)}/><VectorEditor label="POSITION (PIXELS)" value={selectedTrack.position} onChange={value=>setTrackValue("position",value)}/><button onClick={deleteKeyframe}>Remove key at tick</button></div></>:<p>Select a model part to edit its bone and keyframes.</p>}</div></>:<button className="animation-empty" onClick={addClip}>Create the first animation clip</button>}
      </div>
    </section>}
    {libraryOpen&&<div className="library-overlay" onMouseDown={()=>setLibraryOpen(false)}><section className="library-dialog" role="dialog" aria-modal="true" aria-labelledby="library-heading" onMouseDown={event=>event.stopPropagation()}>
      <header className="library-dialog-header"><div><span className="eyebrow">CONTENT LIBRARY</span><h2 id="library-heading">Models, structures and mod packs</h2><p>{library.length} projects · organized for export</p></div><div className="library-header-actions"><button onClick={newModel}>＋ New model</button><button onClick={newCharacter}>New character</button><button onClick={newStructure}>▦ New structure</button><button onClick={()=>modelInput.current?.click()}>Import JSON</button><button className="dialog-close" aria-label="Close library" onClick={()=>setLibraryOpen(false)}>×</button><input ref={modelInput} hidden type="file" accept=".json,application/json" onChange={importModel}/></div></header>
      <nav className="library-type-tabs" role="tablist" aria-label="Library content types">{LIBRARY_CONTENT_TYPES.map(type=>{const count=type==="All Content"?library.length:library.filter(model=>libraryContentType(model)===type).length;return <button key={type} role="tab" aria-selected={libraryType===type} className={libraryType===type?"active":""} onClick={()=>setLibraryType(type)}><span>{type}</span><i>{count}</i></button>})}</nav>
      <div className="library-filters"><label className="library-search">SEARCH<input autoFocus value={librarySearch} onChange={event=>setLibrarySearch(event.target.value)} placeholder="Search models, packs, or collections…"/></label><label>MOD PACK<select value={libraryPack} onChange={event=>setLibraryPack(event.target.value)}>{packOptions.map(pack=><option key={pack}>{pack}</option>)}</select></label><label>CATEGORY<select value={libraryFilter} onChange={event=>setLibraryFilter(event.target.value)}>{categoryTabs.map(category=><option key={category}>{category}</option>)}</select></label><button onClick={()=>{setLibraryType("All Content");setLibrarySearch("");setLibraryPack("All Packs");setLibraryFilter("All")}}>Clear filters</button></div>
      <div className="library-dialog-body"><aside className="library-organizer"><span className="eyebrow">CURRENT MODEL</span><h3>{project.name}</h3><label>MOD PACK<input value={projectPack(project)} onChange={event=>organize({pack:event.target.value})}/></label><label>CATEGORY<select value={projectCategory(project)} onChange={event=>organize({category:event.target.value})}>{CATEGORY_OPTIONS.map(category=><option key={category}>{category}</option>)}</select></label><label>COLLECTION<input value={projectGroup(project)} onChange={event=>organize({group:event.target.value})}/></label><p>Mod packs contain related content. Collections organize sets inside a pack, such as swords and pickaxes.</p><div className="organizer-actions"><button onClick={duplicate}>Duplicate</button><button onClick={()=>download(project.name,minecraftJson(project))}>Model JSON</button>{project.source==="local"&&<button className="danger" onClick={deleteModel}>Delete</button>}</div></aside>
        <div className="library-results">{visibleGroups.length?visibleGroups.map(([key,models])=>{const[pack,collection]=key.split("|||"),collectionModels=library.filter(model=>projectPack(model)===pack&&projectGroup(model)===collection);return <section className="library-section" key={key}><header><div><small>{pack}</small><h3>{collection}</h3></div><div className="library-section-actions"><span>{collectionModels.length} {collectionModels.length===1?"model":"models"}</span><button onClick={()=>void exportCollectionBundle(collectionModels,pack,collection)}>Export collection ZIP</button>{collectionModels.some(model=>model.skin)&&<button onClick={()=>void exportNpcSkinCollection(collectionModels,pack,collection)}>Export NPC skins ZIP</button>}</div></header><div className="library-grid">{models.map(model=><article key={model.id} className={`library-model ${project.id===model.id?"active":""}`}><button className="library-model-open" onClick={()=>{open(model);setLibraryOpen(false)}}><span className="library-model-art"><ModelThumbnail model={model}/><i>{model.sprite?"16px":`${model.cubes.length} parts`}</i></span><span className="library-model-copy"><strong>{model.name}</strong><small>{projectCategory(model)} · {modelKind(model)}</small>{hasPlacementFootprint(model)&&<span className="library-footprint">{placementFootprint(model).join(" × ")} blocks</span>}</span></button><button className="library-model-clone" aria-label={`Clone ${model.name}`} title="Clone into library" onClick={()=>cloneLibraryModel(model)}>⧉</button></article>)}</div></section>}):<div className="library-no-results"><b>No matching models</b><span>Try clearing a filter or searching another name.</span></div>}</div>
      </div>
    </section></div>}
  </main>;
}

function VectorEditor({label,value,onChange}:{label:string;value:Vec3;onChange:(v:Vec3)=>void}){return <fieldset className="vector"><legend>{label}</legend>{["X","Y","Z"].map((axis,i)=><label key={axis}><span>{axis}</span><input type="number" value={value[i]} onChange={e=>{const next=[...value] as Vec3;next[i]=Number(e.target.value);onChange(next)}}/></label>)}</fieldset>}
